// Стратегия (как в оригинале):
//  - taщим за "ручку" (копчёнки); desktop — за весь элемент тоже работает;
//  - перетаскиваемый li следует за указателем через transform; другие li остаются на своих местах;
//  - вставка: ищем ближайший по вертикали другой li и вставляем перетаскиваемый перед/после него
//    в зависимости от того, над/под серединой целевого находится центр перетаскиваемого.
let drag = null;

const onPointerDown = (e) => {
  const li = e.target.closest && e.target.closest(".item");
  if (!li) return;
  const grabHandle = e.target.closest(".handle");
  if (e.pointerType === "mouse" && !grabHandle) return;  // desktop: только за ручку (проще и предсказуемо)
  if (e.pointerType !== "mouse" && !grabHandle) return; // mobile: тоже за ручку
  if (e.pointerType === "mouse" && e.button !== 0) return;
  const ul = li.parentElement;
  const rect = li.getBoundingClientRect();
  drag = {
    li, ul, pointerId: e.pointerId,
    startPointerY: e.clientY,
    liTop: rect.top,
    liHeight: rect.height,
    moved: false,
  };
  try { li.setPointerCapture(e.pointerId); } catch (_) {}
};

const onPointerMove = (e) => {
  if (!drag || e.pointerId !== drag.pointerId) return;
  e.preventDefault();
  const { li, ul } = drag;
  if (!drag.moved) {
    const dy0 = e.clientY - drag.startPointerY;
    if (Math.abs(dy0) < 4) return;
    drag.moved = true;
    li.classList.add("is-dragging");
    ul.classList.add("is-reordering");
  }
  const dy = e.clientY - drag.startPointerY;
  li.style.transform = "translateY(" + dy + "px)";

  const items = Array.from(ul.querySelectorAll(".item")).filter((x) => x !== li);
  for (const o of items) {
    const r = o.getBoundingClientRect();
    o.classList.toggle("is-over", e.clientY > r.top && e.clientY < r.bottom);
  }

  // Центр перетаскиваемого в мировых координатах:
  const virtualTop = drag.liTop + dy;
  const virtualCenter = virtualTop + drag.liHeight / 2;

  // Собираем всех других li с их верхними границами в «мировых» координатах.
  // Определяем, перед каким/после какого вставляем: ищем ближайший по вертикали
  // чужой элемент, чей верх выше virtualCenter, и ближайший, чей верх ниже.
  let prevBest = null, prevBestDist = Infinity;
  let nextBest = null, nextBestDist = Infinity;
  for (const o of items) {
    const r = o.getBoundingClientRect();
    const mid = r.top + r.height / 2;
    if (mid < virtualCenter) {
      const d = virtualCenter - mid;
      if (d < prevBestDist) { prevBestDist = d; prevBest = o; }
    } else {
      const d = mid - virtualCenter;
      if (d < nextBestDist) { nextBestDist = d; nextBest = o; }
    }
  }

  // Вставляем между prevBest и nextBest: перед nextBest (или в конец, если nextBest нет).
  if (nextBest) {
    if (nextBest !== li && nextBest.previousElementSibling !== li) {
      ul.insertBefore(li, nextBest);
    }
  } else if (prevBest) {
    if (prevBest.nextElementSibling !== li) {
      ul.insertBefore(li, prevBest.nextElementSibling);
    }
  }
  refreshRanks(ul);
};

