// Стратегия: при dragstart фиксируем начальную y указателя и позицию li.
// При движении пересчитываем "виртуальное" смещение li (top = исходный top + dy),
// ищем ближайший по вертикали другой li и вставляем перетаскиваемый до/после него.
let drag = null;

const onPointerDown = (e) => {
  const li = e.target.closest && e.target.closest(".item");
  if (!li) return;
  if (!e.target.closest(".handle")) return;
  if (e.pointerType === "mouse" && e.button !== 0) return;
  const ul = li.parentElement;
  const rect = li.getBoundingClientRect();
  drag = {
    li, ul, pointerId: e.pointerId,
    startPointerY: e.clientY,
    liTop: rect.top,
    liHeight: rect.height,
    moved: false,
  };
  try { li.setPointerCapture(e.pointerId); } catch (_) {}
};

const onPointerMove = (e) => {
  if (!drag || e.pointerId !== drag.pointerId) return;
  e.preventDefault();
  const { li, ul } = drag;
  if (!drag.moved) {
    const dy0 = e.clientY - drag.startPointerY;
    if (Math.abs(dy0) < 4) return;
    drag.moved = true;
    li.classList.add("is-dragging");
    ul.classList.add("is-reordering");
  }
  const dy = e.clientY - drag.startPointerY;
  li.style.transform = "translateY(" + dy + "px)";

  const items = Array.from(ul.querySelectorAll(".item")).filter((x) => x !== li);
  for (const o of items) {
    const r = o.getBoundingClientRect();
    o.classList.toggle("is-over", e.clientY > r.top && e.clientY < r.bottom);
  }

  // определяем, перед каким/после какого элемента вставить перетаскиваемый.
  // Используем виртуальный центр перетаскиваемого = liTop + liHeight/2 + dy
  const virtualCenter = drag.liTop + drag.liHeight / 2 + dy;
  let target = null;
  for (const o of items) {
    const r = o.getBoundingClientRect();
    const mid = r.top + r.height / 2;
    if (virtualCenter < mid) {
      if (!target || mid < target.mid) target = { el: o, mid };
    }
  }
  if (target) {
    if (target.el.previousElementSibling !== li) {
      ul.insertBefore(li, target.el);
    }
  } else {
    // ниже всех
    const last = items[items.length - 1];
    if (last && last.nextElementSibling !== li) {
      ul.insertBefore(li, last.nextElementSibling);
    }
  }
  refreshRanks(ul);
};

